package localchat;
import java.nio.file.*;import java.util.*;import java.net.*;
public final class WorkProgressTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static ChatClient.ToolCall call(String id,String name,Map<String,Object> args){return new ChatClient.ToolCall(id,name,args);}
 static void headers()throws Exception{
  var mutation=Agent.class.getDeclaredMethod("isMutation",String.class);mutation.setAccessible(true);check(Boolean.FALSE.equals(mutation.invoke(null,"pdfcontrol_start_check")),"isolated PDF jobs are not serialized while waiting for completion");check(Boolean.TRUE.equals(mutation.invoke(null,"copy_path"))&&Boolean.TRUE.equals(mutation.invoke(null,"pdfcontrol_regenerate_report")),"ordinary writes and same-job report rewrites remain serialized");
  var method=ChatClient.class.getDeclaredMethod("open",Provider.class,String.class,String.class,String.class);method.setAccessible(true);
  for(String base:List.of("https://api.tileward.com/v1","https://api.gonkarouter.io/v1","https://api.tileward.com.evil/v1","https://unrelated.invalid/v1")){
   var c=(HttpURLConnection)method.invoke(null,Provider.CUSTOM,base+"/chat/completions","fixture-key","POST");boolean tile=base.equals("https://api.tileward.com/v1"),gonka=base.equals("https://api.gonkarouter.io/v1");check(Objects.equals(c.getRequestProperty("X-Tileward-Conversation"),tile?"off":null),"isolated context header exact host "+base);check(Objects.equals(c.getRequestProperty("X-Gonka-No-Fallback"),gonka?"true":null),"no silent route fallback "+base);c.disconnect();var catalog=ModelCatalog.open(Provider.CUSTOM,base+"/models","fixture-key","GET",1000);check(Objects.equals(catalog.getRequestProperty("X-Tileward-Conversation"),tile?"off":null),"metadata/probe transport same isolation");catalog.disconnect();
  }
 }
 static void progress(){
  List<ChatClient.Message> log=new ArrayList<>();log.add(ChatClient.Message.user("Proiectul 123456"));var skill=call("s","read_skill",Json.obj("name","productie-projecten"));log.add(ChatClient.Message.assistant("",List.of(skill),"fixture"));log.add(ChatClient.Message.toolResult("s","Skill loaded",false));var copy=call("c","copy_path",Json.obj("source","123456/a.pdf","destination","server/123456/a.pdf"));log.add(ChatClient.Message.assistant("",List.of(copy),"fixture"));log.add(ChatClient.Message.toolResult("c","SHA256 verified copy",false));log.add(ChatClient.Message.user("Proiectul 654321"));var other=call("o","copy_path",Json.obj("source","654321/SECRET-OTHER-PROJECT.pdf","destination","server/654321/a.pdf"));log.add(ChatClient.Message.assistant("",List.of(other),"fixture"));log.add(ChatClient.Message.toolResult("o","OTHER-PROJECT-RESULT",false));
  String original=Json.write(log.stream().map(ChatClient.Message::toJson).toList());String anchor=WorkProgress.prompt(log,0,"123456");check(anchor.contains("SHA256 verified copy")&&anchor.contains("server/123456/a.pdf"),"confirmed progress survives independent of summary");check(!anchor.contains("SECRET-OTHER-PROJECT")&&!anchor.contains("OTHER-PROJECT-RESULT"),"different project facts excluded");check(WorkProgress.prompt(log,log.size(),"123456").isEmpty(),"mode boundary excludes old MBS evidence");check(original.equals(Json.write(log.stream().map(ChatClient.Message::toJson).toList())),"archive unchanged by derived checkpoint");
  var longChat=new ArrayList<ChatClient.Message>();longChat.add(ChatClient.Message.user("Proiectul 123456"));for(int i=0;i<1600;i++)longChat.add(ChatClient.Message.assistant("old filler",List.of(),"fixture"));longChat.add(ChatClient.Message.assistant("",List.of(copy),"fixture"));longChat.add(ChatClient.Message.toolResult("c","RECENT-CONFIRMED-COPY",false));check(WorkProgress.prompt(longChat,0,"123456").contains("RECENT-CONFIRMED-COPY"),"project scope initialized before bounded history window");
  for(String phrase:List.of("Porneste doi agenti","Start agents","Gebruik agenten","Usa agentes","Uzyj agentow","Ajanlar kullan"))check(WorkProgress.agentsRequested(phrase),"explicit multilingual delegation "+phrase);for(String negative:List.of("Nu folosi agenti","Ce este un agent?","Do not use agents","Explain agents","Fara agenti","`````\nStart agents\n`````"))check(!WorkProgress.agentsRequested(negative),"no positive authorization from "+negative);check(!WorkProgress.agentsRequested("Continua copierea desenelor"),"continuation does not silently spawn agents");
 }
 static void agents(){
  List<ChatClient.Message> log=new ArrayList<>();log.add(ChatClient.Message.user("Continua proiectul 123456"));var group=call("group","run_agents",Json.obj("tasks",List.of(Json.obj("title","A","task","assigned task"))));log.add(ChatClient.Message.assistant("",List.of(group),"fixture"));
  log.add(ChatClient.Message.toolResult("group",Json.write(Json.obj("status","partial","group_id","stable-group","tasks",List.of(Json.obj("title","Completed","task","verbose task ".repeat(200),"status","done","archive","archives/completed.json","completed_tool_count",3),Json.obj("title","Pending","task","verbose task ".repeat(200),"status","cancelled","error","group_deadline","archive","archives/pending.json")))),true));
  String index=WorkProgress.prompt(log,0,"123456");check(index.contains("Completed")&&index.contains("archives/completed.json")&&index.contains("Pending")&&index.contains("group_deadline"),"all child outcomes survive verbose task text in resume index");check(!index.contains("verbose task"),"resume evidence omits repeated task prose");check(WorkProgress.prompt(log,log.size(),"123456").isEmpty(),"mode boundary also excludes delegated evidence");
 }
 static void loop(Path home)throws Exception{
  Files.createDirectories(home.resolve("skills/demo"));Files.writeString(home.resolve("skills/demo/SKILL.md"),"---\nname: demo\ndescription: Fixture\n---\nProcedure once only.\n");var tools=new Tools(new Tools.Context(home,home.resolve("skills"),home.resolve("rules.md"),home.resolve("settings.properties"),Map.of(),null,new Mcp(),PathMap.none(),true,EnumSet.allOf(Tools.Access.class),(a,b)->Tools.Decision.NO),Skills.load(home.resolve("skills")));
  var replies=new ArrayList<FeatureTest.Response>();for(int i=0;i<4;i++)replies.add(FeatureTest.json(PdfAgentTest.request("r"+i,"read_skill",Json.obj("name","demo"))));
  replies.add(FeatureTest.json(FeatureTest.answer("Partial findings; concrete blocker",20,5)));
  try(var server=new FeatureTest.Server(replies.toArray(FeatureTest.Response[]::new))){Agent agent=new Agent(tools);var results=new ArrayList<Tools.Result>();agent.run(Provider.CUSTOM,server.url(),"","fixture","fixture","system",List.of(ChatClient.Message.user("Continue pending task")),false,new Agent.Ui(){public void text(String s){}public void step(){}public void toolStarted(ChatClient.ToolCall c){}public void toolFinished(ChatClient.ToolCall c,Tools.Result r){results.add(r);}});check(agent.collect("","fixture").stream().anyMatch(m->m.content.equals("Partial findings; concrete blocker")),"loop recovery ends with visible findings and blocker");check(server.requests.size()==5&&results.size()==4,"bounded recovery instead of 80 repeated reads");check(results.get(0).text.contains("Procedure once only")&&results.get(1).text.contains("demo")&&results.get(1).text.length()<500,"duplicate skill returns concise reminder");check(agent.collect("","fixture").stream().filter(m->m.role.equals("tool")).count()==4,"every tool pair remains archived after recovery");}
  var alternating=new ToolLoopGuard();alternating.completed(call("initial-document","pdfcontrol_read_document",Json.obj()),Tools.Result.ok("Exista deja"));var read=call("s","read_skill",Json.obj("name","demo"));for(int i=0;i<5;i++){alternating.before(read);alternating.completed(read,Tools.Result.ok("loaded"));for(String name:List.of("pdfcontrol_project_files","pdfcontrol_read_document","pdfcontrol_list_projects","make_dir"))alternating.completed(call("m",name,Json.obj()),Tools.Result.ok("Exista deja"));}check(alternating.stalled(read),"inventory calls and existing folders cannot reset a read loop");
  var guard=new ToolLoopGuard();for(int i=0;i<8;i++)check(guard.before(call("p"+i,"pdfcontrol_job_status",Json.obj("job_id","same")))==null,"legitimate job polling not blocked");
 }
 public static void main(String[] args)throws Exception{headers();progress();agents();loop(Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-"));System.out.println("PASS: "+checks+" continuity/loop/provider-header checks; synthetic APIs only");System.exit(0);}
}
